CustomField.formula:
OR(
    /* Case 1: Monthly invoices → 2nd day of each month */
    AND(
        ISPICKVAL( Billing_Term__c , "Monthly"),
        DAY(TODAY()) = 29
    ),

    /* Case 2: Quarterly invoices → 3 days after quarter end */
    AND(
        ISPICKVAL(Billing_Term__c, "Quarterly"),
        OR(
            AND(MONTH(TODAY()) = 1, DAY(TODAY()) = 3),   /* Jan 3 (Q4 end) */
            AND(MONTH(TODAY()) = 4, DAY(TODAY()) = 3),   /* Apr 3 (Q1 end) */
            AND(MONTH(TODAY()) = 7, DAY(TODAY()) = 3),   /* Jul 3 (Q2 end) */
            AND(MONTH(TODAY()) = 10, DAY(TODAY()) = 3)   /* Oct 3 (Q3 end) */
        )
    )
)
